namespace sv_c160bb9e935c43dbbe41506acfdab27d.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@namespace sv_c160bb9e935c43dbbe41506acfdab27d.Components.Pages.Settings

<nav class="settings-sidebar">
    <ul class="settings-nav">
        @foreach (var section in Sections)
        {
            <li class="settings-nav-item @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="nav-icon">@GetIcon(section)</span>
                <span class="nav-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_c160bb9e935c43dbbe41506acfdab27d.Components.Pages.Settings
@using sv_c160bb9e935c43dbbe41506acfdab27d.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Profile Settings</h2>

    @if (_loading)
    {
        <p class="loading">Loading profile...</p>
    }
    else
    {
        <div class="profile-form">
            <div class="avatar-preview">
                <img src="@_avatarUrl" alt="Avatar" class="avatar-image" />
                <div class="avatar-url">
                    <label>Avatar URL</label>
                    <input type="text" @bind="_avatarUrl" placeholder="https://..." />
                </div>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="_displayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="_email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" @bind="_bio" rows="4"></textarea>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveChanges" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save Changes")
                </button>
                <button class="btn btn-secondary" @onclick="DiscardChanges">Discard Changes</button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast toast-success">Profile saved successfully!</div>
            }
            @if (_errorMessage is not null)
            {
                <div class="toast toast-error">@_errorMessage</div>
            }
        </div>
    }
</div>

@code {
    private string _displayName = "";
    private string _email = "";
    private string _avatarUrl = "";
    private string _bio = "";
    private UserProfile? _savedProfile;
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;
    private string? _errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
    }

    private async Task LoadProfile()
    {
        _loading = true;
        _savedProfile = await SettingsService.GetProfileAsync();
        ApplyProfile(_savedProfile);
        _loading = false;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _avatarUrl = profile.AvatarUrl;
        _bio = profile.Bio;
    }

    private async Task SaveChanges()
    {
        _saving = true;
        _showSuccess = false;
        _errorMessage = null;

        try
        {
            var profile = new UserProfile(_displayName, _email, _avatarUrl, _bio);
            await SettingsService.SaveProfileAsync(profile);
            _savedProfile = profile;
            _showSuccess = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to save: {ex.Message}";
        }
        finally
        {
            _saving = false;
        }
    }

    private void DiscardChanges()
    {
        if (_savedProfile is not null)
        {
            ApplyProfile(_savedProfile);
        }
        _showSuccess = false;
        _errorMessage = null;
    }
}

@namespace sv_c160bb9e935c43dbbe41506acfdab27d.Components.Pages.Settings
@using sv_c160bb9e935c43dbbe41506acfdab27d.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Notification Preferences</h2>

    @if (_loading)
    {
        <p class="loading">Loading preferences...</p>
    }
    else
    {
        <div class="notifications-form">
            <div class="toggle-group">
                <label class="toggle-item">
                    <input type="checkbox" @bind="_emailNotifications" />
                    <span class="toggle-label">Email Notifications</span>
                    <span class="toggle-description">Receive notifications via email</span>
                </label>

                <label class="toggle-item">
                    <input type="checkbox" @bind="_pushNotifications" />
                    <span class="toggle-label">Push Notifications</span>
                    <span class="toggle-description">Receive browser push notifications</span>
                </label>

                <label class="toggle-item">
                    <input type="checkbox" @bind="_weeklyDigest" />
                    <span class="toggle-label">Weekly Digest</span>
                    <span class="toggle-description">Receive a weekly summary email</span>
                </label>
            </div>

            @if (_mutedChannels.Count > 0)
            {
                <div class="muted-channels">
                    <h3>Muted Channels</h3>
                    <p class="section-description">Uncheck to unmute a channel</p>
                    <div class="channel-list">
                        @foreach (var channel in _allChannels)
                        {
                            <label class="channel-item">
                                <input type="checkbox"
                                       checked="@_mutedChannels.Contains(channel)"
                                       @onchange="(e) => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                                <span>@channel</span>
                            </label>
                        }
                    </div>
                </div>
            }

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SavePreferences" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save Preferences")
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast toast-success">Preferences saved successfully!</div>
            }
        </div>
    }
</div>

@code {
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _mutedChannels = new();
    private List<string> _allChannels = new();
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = prefs.EmailNotifications;
        _pushNotifications = prefs.PushNotifications;
        _weeklyDigest = prefs.WeeklyDigest;
        _mutedChannels = new List<string>(prefs.MutedChannels);
        _allChannels = new List<string>(prefs.MutedChannels);
        _loading = false;
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        _saving = true;
        _showSuccess = false;

        var prefs = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, _mutedChannels);
        await SettingsService.SaveNotificationPrefsAsync(prefs);

        _saving = false;
        _showSuccess = true;
    }
}

@namespace sv_c160bb9e935c43dbbe41506acfdab27d.Components.Pages.Settings
@using sv_c160bb9e935c43dbbe41506acfdab27d.Services
@inject ISettingsService SettingsService

<div class="expandable-panel">
    <button class="panel-header" @onclick="() => _expanded = !_expanded">
        <span>Change Password</span>
        <span class="expand-icon">@(_expanded ? "▲" : "▼")</span>
    </button>

    @if (_expanded)
    {
        <div class="panel-content">
            <div class="form-group">
                <label for="currentPassword">Current Password</label>
                <input id="currentPassword" type="password" @bind="_currentPassword" />
            </div>

            <div class="form-group">
                <label for="newPassword">New Password</label>
                <input id="newPassword" type="password" @bind="_newPassword" />
            </div>

            <div class="form-group">
                <label for="confirmPassword">Confirm Password</label>
                <input id="confirmPassword" type="password" @bind="_confirmPassword" />
            </div>

            @if (_errorMessage is not null)
            {
                <div class="toast toast-error">@_errorMessage</div>
            }
            @if (_showSuccess)
            {
                <div class="toast toast-success">Password updated successfully!</div>
            }

            <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@_saving">
                @(_saving ? "Updating..." : "Update Password")
            </button>
        </div>
    }
</div>

@code {
    private bool _expanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _errorMessage;
    private bool _showSuccess;
    private bool _saving;

    private async Task UpdatePassword()
    {
        _errorMessage = null;
        _showSuccess = false;

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _errorMessage = "All password fields are required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _errorMessage = "New password and confirmation do not match.";
            return;
        }

        _saving = true;
        try
        {
            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
            _showSuccess = true;
            _currentPassword = "";
            _newPassword = "";
            _confirmPassword = "";
        }
        catch (Exception ex)
        {
            _errorMessage = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
}

@namespace sv_c160bb9e935c43dbbe41506acfdab27d.Components.Pages.Settings
@using sv_c160bb9e935c43dbbe41506acfdab27d.Services

<div class="sessions-section">
    <h3>Active Sessions</h3>

    @if (Sessions is null || Sessions.Count == 0)
    {
        <p>No active sessions.</p>
    }
    else
    {
        <table class="sessions-table">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in Sessions)
                {
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@session.LastActive.ToString("g")</td>
                        <td>
                            @if (session.Id != CurrentSessionId)
                            {
                                <button class="btn btn-danger btn-sm"
                                        @onclick="() => PromptRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="badge badge-current">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    }

    @if (_sessionToRevoke is not null)
    {
        <div class="modal-overlay">
            <div class="modal-dialog">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                <div class="modal-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevoke" disabled="@_revoking">
                        @(_revoking ? "Revoking..." : "Revoke")
                    </button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public List<ActiveSession>? Sessions { get; set; }
