@namespace sv_c160bb9e935c43dbbe41506acfdab27d.Components.Pages.Settings
@using sv_c160bb9e935c43dbbe41506acfdab27d.Services
@inject ISettingsService SettingsService

<div class="settings-section">
    <h2>Appearance</h2>

    @if (_loading)
    {
        <p class="loading">Loading appearance settings...</p>
    }
    else
    {
        <div class="appearance-form">
            <div class="form-group">
                <h3>Theme</h3>
                <div class="radio-group">
                    @foreach (var theme in _themes)
                    {
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@theme"
                                   checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <span>@theme</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <h3>Font Size</h3>
                <div class="radio-group">
                    @foreach (var size in _fontSizes)
                    {
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@size"
                                   checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <span>@size</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <h3>Language</h3>
                <select @bind="_language" class="form-select">
                    @foreach (var lang in _languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="form-group">
                <label class="toggle-item">
                    <input type="checkbox" @bind="_compactMode" />
                    <span class="toggle-label">Compact Mode</span>
                    <span class="toggle-description">Reduce spacing and padding throughout the UI</span>
                </label>
            </div>

            <div class="appearance-preview" style="@GetPreviewStyle()">
                <h4>Live Preview</h4>
                <p>This is how your content will look with the selected settings.</p>
                <button class="btn btn-primary">Sample Button</button>
            </div>

            <div class="form-actions">
                <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@_saving">
                    @(_saving ? "Saving..." : "Save")
                </button>
            </div>

            @if (_showSuccess)
            {
                <div class="toast toast-success">Appearance settings saved!</div>
            }
        </div>
    }
</div>

@code {
    private static readonly string[] _themes = { "Light", "Dark", "System" };
    private static readonly string[] _fontSizes = { "Small", "Medium", "Large" };
    private static readonly string[] _languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };

    private string _theme = "System";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private bool _showSuccess;

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private string GetPreviewStyle()
    {
        var bg = _theme switch
        {
            "Dark" => "background-color: #1e1e1e; color: #e0e0e0;",
            "Light" => "background-color: #ffffff; color: #333333;",
            _ => "background-color: #f5f5f5; color: #333333;"
        };

        var font = _fontSize switch
        {
            "Small" => "font-size: 0.85rem;",
            "Large" => "font-size: 1.2rem;",
            _ => "font-size: 1rem;"
        };

        var padding = _compactMode ? "padding: 0.5rem;" : "padding: 1.5rem;";

        return $"{bg} {font} {padding} border-radius: 8px; border: 1px solid #ddd; margin: 1rem 0;";
    }

    private async Task SaveAppearance()
    {
        _saving = true;
        _showSuccess = false;

        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(settings);

        _saving = false;
        _showSuccess = true;
    }
}

